# The reference data of `test/grid_tensor.jl`: the entries of GeometricBrackets' `PoissonTensor`
# on the small grids that test compares `GridTensor` against.
#
# The data is stored rather than generated by the test, because `test/Project.toml` must not hold
# GeometricBrackets: every GeometricBrackets 0.x needs Julia 1.11 (General's
# `G/GeometricBrackets/Compat.toml` gives `julia = "1.11.0 - 1"` for its `[0]` range), while this
# package's floor is 1.10, so CI's `Julia min` job could not set up the test environment.
#
# Run it from the repository root, in a scratch environment that holds GeometricBrackets 0.1.2:
#
#   julia +1.11 --startup-file=no -e 'import Pkg; Pkg.activate(; temp = true); Pkg.add(name = "GeometricBrackets", version = "0.1.2"); include("test/helpers/generate_poisson_tensor_reference.jl")'
#
# It writes one file per case into `test/data/`: `poisson_tensor_<DT>_<nx>x<nv>.txt`, one line per
# nonzero entry of `Array(PoissonTensor(DT, nx, nv, Arakawa(nx, nv, DT(0.5), DT(0.25))))`, as
# `<i> <j> <k> <value>` with the three indices linear on the `nx × nv` grid, in the order of
# `LinearIndices((nx, nv))`, and the value in `%.17e`. `parse(DT, …)` reads a `Float32` value back
# bit for bit, because `%.17e` prints the exact widening of its `Float64`. A re-run writes the
# same bytes, because the entries come out in the order of `findall(!iszero, A)`.

using GeometricBrackets
using Printf

pkgversion(GeometricBrackets) == v"0.1.2" || error(
    "this generator writes the reference data of GeometricBrackets 0.1.2, got " *
    "$(pkgversion(GeometricBrackets))")

const DATA = joinpath(@__DIR__, "..", "data")

"Write one case's nonzero entries, and return its path and their number."
function write_case(DT, nx, nv)
    arakawa = Arakawa(nx, nv, DT(0.5), DT(0.25))
    A = Array(PoissonTensor(DT, nx, nv, arakawa))
    path = joinpath(DATA, "poisson_tensor_$(DT)_$(nx)x$(nv).txt")
    entries = 0
    open(path, "w") do io
        for I in findall(!iszero, A)
            println(io, I[1], ' ', I[2], ' ', I[3], ' ', @sprintf("%.17e", A[I]))
            entries += 1
        end
    end
    return path, entries
end

mkpath(DATA)
for DT in (Float32, Float64), (nx, nv) in ((3, 4), (4, 5))

    path, entries = write_case(DT, nx, nv)
    println("$(relpath(path, pwd())): $entries entries")
end
